const ICT_OFFSET_MS = 7 * 60 * 60 * 1000;

/** The UTC instant of the most recent ICT midnight (00:00 ICT) at or before `now`. */
export function startOfTodayICT(now: Date = new Date()): Date {
  const shifted = new Date(now.getTime() + ICT_OFFSET_MS);
  shifted.setUTCHours(0, 0, 0, 0);
  return new Date(shifted.getTime() - ICT_OFFSET_MS);
}

/** IPs the admin has chosen to exclude from analytics (their own IP, office IP,
 *  a noisy bot) so the numbers reflect ACTUAL public traffic. Stored as a
 *  comma-separated setting. */
export async function excludedIps(): Promise<string[]> {
  const raw = (await getSetting("analytics_excluded_ips")) ?? "";
  return raw.split(",").map((s) => s.trim()).filter(Boolean);
}

/** Prisma where-fragment every visitor-analytics read spreads into its `where`:
 *  drops the admin's excluded IPs AND bot traffic (`isBot = false`, see
 *  lib/bots/*). Bots are excluded by default; the admin "include bots" toggle
 *  (cookie, lib/bots/scope.ts) lifts only the bot filter, never the IP list.
 *  Outside a request (worker rollups) bots are always excluded. */
async function ipEx(): Promise<{ ip?: { notIn: string[] }; isBot?: boolean }> {
  const [e, bots] = await Promise.all([excludedIps(), botWhere()]);
  return { ...(e.length ? { ip: { notIn: e } } : {}), ...bots };
}

