/**
 * Pure helpers for the growth scoreboard / human funnel (mkt-003, mkt-019,
 * mkt-033). No I/O so the unit tests and the report generator agree.
 */

const DAY = 86_400_000;
export { DAY };

/** UTC Monday 00:00 of the week containing `d`. */
export function weekStartUtc(d: Date): Date {
  const x = new Date(Date.UTC(d.getUTCFullYear(), d.getUTCMonth(), d.getUTCDate()));
  const dow = (x.getUTCDay() + 6) % 7; // Mon=0 .. Sun=6
  return new Date(x.getTime() - dow * DAY);
}

/** The most recent COMPLETED Mon-Sun week as of `now` (the week the Monday report covers). */
export function lastCompletedWeekStart(now: Date): Date {
  return new Date(weekStartUtc(now).getTime() - 7 * DAY);
}

/** `YYYY-MM-DD` of a week start, the stable cohort / report key. */
export function weekKey(d: Date): string {
  return weekStartUtc(d).toISOString().slice(0, 10);
}

/** A ratio as a percentage rounded to 1 dp, or null when the denominator is 0 (never a fake 0%). */
export function pct(n: number, d: number): number | null {
  if (!Number.isFinite(n) || !Number.isFinite(d) || d <= 0) return null;
  return Math.round((n / d) * 1000) / 10;
}

/**
 * Has a cohort's window fully elapsed? A signup cohort (week starting `start`)
 * is "mature at N days" only when its LAST signup (start + 7d) has had N days
 * to convert. Reporting an immature cohort's 30-day rate would understate it.
 */
export function cohortMature(start: Date, windowDays: number, now: Date): boolean {
  return start.getTime() + 7 * DAY + windowDays * DAY <= now.getTime();
}

/** Did `eventAt` happen within `windowDays` of `signupAt` (and not before it)? */
export function withinDays(signupAt: Date, eventAt: Date | null | undefined, windowDays: number): boolean {
  if (!eventAt) return false;
  const dt = eventAt.getTime() - signupAt.getTime();
  return dt >= 0 && dt <= windowDays * DAY;
}

export function median(xs: number[]): number | null {
  if (!xs.length) return null;
  const s = [...xs].sort((a, b) => a - b);
  const m = Math.floor(s.length / 2);
  return s.length % 2 ? s[m] : (s[m - 1] + s[m]) / 2;
}

export type StepIn = { step: string; reached: number };
export type StepConv = { step: string; reached: number; fromPrevPct: number | null; fromFirstPct: number | null };

/** Step-to-step conversion for an ordered wizard funnel. */
export function stepConversion(steps: StepIn[]): StepConv[] {
  const first = steps[0]?.reached ?? 0;
  return steps.map((s, i) => ({
    step: s.step,
    reached: s.reached,
    fromPrevPct: i === 0 ? null : pct(s.reached, steps[i - 1].reached),
    fromFirstPct: i === 0 ? null : pct(s.reached, first),
  }));
}

/** Postfix deferral share. Null when nothing was sampled. */
export function deferralRate(sent: number, deferred: number, bounced: number): number | null {
  return pct(deferred, sent + deferred + bounced);
}
