cd /opt/nxeon-wt-g1; cat > lib/growth/human-funnel.ts <<'E'
/**
 * Human-only traffic quality + funnel (mkt-003).
 *
 * The classifier itself (lib/bots/*) shipped 2026-10-01 and already keeps bots out
 * of every default visitor number. What was missing is a place that SHOWS how much
 * of the traffic was removed and recomputes the conversion funnel strictly from
 * human sessions, so a conversion rate can finally be read:
 *
 *   trafficQuality()  raw vs human views / visitors / sessions, bot share by kind
 *                     and reason, and device + country computed from BOTH so the
 *                     "desktop 22,234 vs mobile 558" skew can be seen going away.
 *   humanFunnel()     human visitors -> human sessions -> sessions that opened
 *                     /register -> signups -> deployed -> paid.
 *
 * Both are independent of the admin "include bots" cookie on purpose: they always
 * show the raw and the human number side by side. Human = `isBot = false` (the same
 * definition every other analytics read uses) and not one of the admin's excluded IPs.
 *
 * Distinct counts use COALESCE(visitorId, ip) for people and
 * COALESCE(sessionId, visitorId, ip) for sessions, computed in SQL (exact, no row cap).
 */
import { Prisma } from "@prisma/client";
import { db } from "@/lib/db";
import { excludedIps } from "@/lib/analytics";
import { CUSTOMER_WHERE, DEPLOYED_STATUSES } from "@/lib/insights/common";
import { REVENUE_WHERE } from "@/lib/admin-metrics";
import { REAL_CASH_IN_WHERE } from "@/lib/revenue";
import { pct } from "./pure";

export type Tally = { views: number; visitors: number; sessions: number };
export type Labeled = { label: string; raw: number; human: number };

export type TrafficQuality = {
  from: string;
  to: string;
  raw: Tally;
  human: Tally;
  /** Share of raw page views that were classified as bots (0-100), null if no traffic. */
  botSharePct: number | null;
  byKind: { kind: string; views: number; visitors: number }[];
  topBotReasons: { reason: string; views: number }[];
  devices: Labeled[];
  countries: Labeled[];
  /** Rows not classified yet (botKind null): counted as human until the backfill / re-classifier reaches them. */
  unclassifiedRows: number;
};

function exIp(ips: string[]): Prisma.Sql {
  return ips.length ? Prisma.sql`AND "ip" NOT IN (${Prisma.join(ips)})` : Prisma.empty;
}

async function tally(from: Date, to: Date, humanOnly: boolean, ips: string[]): Promise<Tally> {
  const rows = await db.$queryRaw<{ views: bigint; visitors: bigint; sessions: bigint }[]>(Prisma.sql`
    SELECT COUNT(*) AS views,
           COUNT(DISTINCT COALESCE("visitorId", "ip")) AS visitors,
           COUNT(DISTINCT COALESCE("sessionId", "visitorId", "ip")) AS sessions
    FROM "Visit"
    WHERE "createdAt" >= ${from} AND "createdAt" < ${to}
      ${humanOnly ? Prisma.sql`AND "isBot" = false` : Prisma.empty}
      ${exIp(ips)}`);
  const r = rows[0];
  return { views: Number(r?.views ?? 0), visitors: Number(r?.visitors ?? 0), sessions: Number(r?.sessions ?? 0) };
}

async function dim(col: "deviceType" | "country", from: Date, to: Date, ips: string[], limit: number): Promise<Labeled[]> {
  const c = Prisma.raw(`"${col}"`);
  const rows = await db.$queryRaw<{ label: string | null; raw: bigint; human: bigint }[]>(Prisma.sql`
    SELECT COALESCE(${c}, 'Unknown') AS label,
           COUNT(*) AS raw,
           COUNT(*) FILTER (WHERE "isBot" = false) AS human
    FROM "Visit"
    WHERE "createdAt" >= ${from} AND "createdAt" < ${to} ${exIp(ips)}
    GROUP BY 1 ORDER BY raw DESC LIMIT ${limit}`);
  return rows.map((r) => ({ label: r.label ?? "Unknown", raw: Number(r.raw), human: Number(r.human) }));
}

export async function trafficQuality(from: Date, to: Date): Promise<TrafficQuality> {
  const ips = await excludedIps();
  const [raw, human, kinds, reasons, devices, countries, unclassified] = await Promise.all([
    tally(from, to, false, ips),
    tally(from, to, true, ips),
    db.$queryRaw<{ kind: string | null; views: bigint; visitors: bigint }[]>(Prisma.sql`
      SELECT COALESCE("botKind", 'unclassified') AS kind, COUNT(*) AS views,
             COUNT(DISTINCT COALESCE("visitorId", "ip")) AS visitors
      FROM "Visit" WHERE "createdAt" >= ${from} AND "createdAt" < ${to} ${exIp(ips)}
      GROUP BY 1 ORDER BY views DESC`),
    // First reason token only ("dc-ip:aws", "ua:lightpanda", "stale-browser:chrome/119"...).
    db.$queryRaw<{ reason: string | null; views: bigint }[]>(Prisma.sql`
      SELECT split_part("botReason", ',', 1) AS reason, COUNT(*) AS views
      FROM "Visit" WHERE "createdAt" >= ${from} AND "createdAt" < ${to} AND "isBot" = true
        AND "botReason" IS NOT NULL ${exIp(ips)}
      GROUP BY 1 ORDER BY views DESC LIMIT 12`),
    dim("deviceType", from, to, ips, 8),
    dim("country", from, to, ips, 10),
    db.visit.count({ where: { createdAt: { gte: from, lt: to }, botKind: null, isBot: false } }),
  ]);
  return {
    from: from.toISOString(),
    to: to.toISOString(),
    raw,
    human,
    botSharePct: pct(raw.views - human.views, raw.views),
    byKind: kinds.map((k) => ({ kind: k.kind ?? "unclassified", views: Number(k.views), visitors: Number(k.visitors) })),
    topBotReasons: reasons.map((r) => ({ reason: r.reason ?? "(none)", views: Number(r.views) })),
    devices,
    countries,
    unclassifiedRows: unclassified,
  };
}

export type HumanFunnel = {
  from: string;
  to: string;
  humanVisitors: number;
  humanSessions: number;
  /** Human sessions that opened the registration page. */
  registerSessions: number;
  /** Customer accounts created in the window (internal/test accounts excluded). */
  signups: number;
  /** Of those signups: got a real server (or a free MC server) by now. */
  deployed: number;
  /** Of those signups: made a real payment or have earned revenue by now. */
  paid: number;
  /** Same visitors/sessions with bots included, to show what the filter removed. */
  rawVisitors: number;
  rawSessions: number;
};

export async function humanFunnel(from: Date, to: Date): Promise<HumanFunnel> {
  const ips = await excludedIps();
  const [human, raw, reg, users] = await Promise.all([
    tally(from, to, true, ips),
    tally(from, to, false, ips),
    db.$queryRaw<{ n: bigint }[]>(Prisma.sql`
      SELECT COUNT(DISTINCT COALESCE("sessionId", "visitorId", "ip")) AS n
      FROM "Visit"
      WHERE "createdAt" >= ${from} AND "createdAt" < ${to} AND "isBot" = false
        AND ("path" = '/register' OR "path" LIKE '/register?%' OR "path" LIKE '/register/%') ${exIp(ips)}`),
    db.user.findMany({ where: { ...CUSTOMER_WHERE, createdAt: { gte: from, lt: to } }, select: { id: true }, take: 50_000 }),
  ]);
  const ids = users.map((u) => u.id);
  let deployed = 0;
  let paid = 0;
  if (ids.length) {
    const [servers, freemc, cash, debit] = await Promise.all([
      db.server.findMany({ where: { userId: { in: ids }, status: { in: [...DEPLOYED_STATUSES] } }, distinct: ["userId"], select: { userId: true } }),
      db.freeMinecraftServer.findMany({ where: { userId: { in: ids } }, select: { userId: true } }),
      db.walletTransaction.findMany({ where: { ...REAL_CASH_IN_WHERE, userId: { in: ids } }, distinct: ["userId"], select: { userId: true } }),
      db.walletTransaction.findMany({ where: { ...REVENUE_WHERE, userId: { in: ids } }, distinct: ["userId"], select: { userId: true } }),
    ]);
    const dep = new Set<string>([...servers.map((s) => s.userId), ...freemc.map((f) => f.userId)]);
    const pay = new Set<string>([...cash.map((c) => c.userId), ...debit.map((d) => d.userId)]);
    deployed = ids.filter((i) => dep.has(i)).length;
    paid = ids.filter((i) => pay.has(i)).length;
  }
  return {
    from: from.toISOString(),
    to: to.toISOString(),
    humanVisitors: human.visitors,
    humanSessions: human.sessions,
    registerSessions: Number(reg[0]?.n ?? 0),
    signups: ids.length,
    deployed,
    paid,
    rawVisitors: raw.visitors,
    rawSessions: raw.sessions,
  };
}
E

