/**
 * Free-Minecraft funnel, end to end, by signup week (mkt-019).
 *
 *   visits      human page views of /free-minecraft* (top of funnel, from Visit, bot-free)
 *   created     a free server exists                      FreeMinecraftServer.createdAt
 *   woke        its first real wake was observed          firstWakeAt  (else any WAKE event)
 *   multiplayer first time 2+ players were on at once     firstMultiplayerAt (else any sample with players >= 2)
 *   prompted    an upgrade prompt was SHOWN to the owner  FreeMinecraftUpsellEvent (lib/freemc-upsell.ts triggers)
 *   clicked     the owner CLICKED an upgrade prompt
 *   paid        the owner made a real payment or has earned revenue AFTER creating the server
 *
 * Cohorts are the week the OWNER's account was created (the brief's "signup week"),
 * Monday-start UTC. Honesty rules baked in:
 *  - The milestone columns only exist from this deploy forward. For servers created
 *    before then the fallback reads whatever raw evidence is left (events 90d,
 *    samples 14d), which is a LOWER BOUND; `coverage` says how many rows came from
 *    the durable column vs the fallback.
 *  - "prompted" can only be non-zero for owners who saw the dashboard while the
 *    upsell flag was on and a real signal fired; it is not "eligible", it is "shown".
 *  - A rate whose denominator is 0 is null, never 0%.
 */
import { Prisma } from "@prisma/client";
import { db } from "@/lib/db";
import { CUSTOMER_WHERE } from "@/lib/insights/common";
import { REVENUE_WHERE } from "@/lib/admin-metrics";
import { REAL_CASH_IN_WHERE } from "@/lib/revenue";
import { excludedIps } from "@/lib/analytics";
import { DAY, pct, weekKey, weekStartUtc } from "./pure";

export type FreeMcCohort = {
  week: string; // signup week (Monday, UTC)
  created: number;
  woke: number;
  multiplayer: number;
  prompted: number;
  clicked: number;
  paid: number;
  paidAfterClick: number;
  createdToMultiplayerPct: number | null;
  createdToPaidPct: number | null;
};

export type FreeMcFunnel = {
  from: string;
  to: string;
  humanVisits: number;
  humanVisitors: number;
  totals: Omit<FreeMcCohort, "week">;
  cohorts: FreeMcCohort[];
  triggers: { trigger: string; shownUsers: number; clickedUsers: number; clickRatePct: number | null }[];
  coverage: { createdTotal: number; wokeFromColumn: number; wokeFromFallback: number; multiplayerFromColumn: number; multiplayerFromFallback: number };
  notes: string[];
};

/** Pure: fold per-server facts into weekly cohorts. Exported for tests. */
export type ServerFact = {
  userId: string;
  signupAt: Date;
  createdAt: Date;
  woke: boolean;
  multiplayer: boolean;
  prompted: boolean;
  clickedAt: Date | null;
  paidAt: Date | null;
};

export function buildCohorts(facts: ServerFact[]): { cohorts: FreeMcCohort[]; totals: Omit<FreeMcCohort, "week"> } {
  const blank = (): Omit<FreeMcCohort, "week" | "createdToMultiplayerPct" | "createdToPaidPct"> => ({
    created: 0, woke: 0, multiplayer: 0, prompted: 0, clicked: 0, paid: 0, paidAfterClick: 0,
  });
  const by = new Map<string, ReturnType<typeof blank>>();
  const tot = blank();
  for (const f of facts) {
    const k = weekKey(f.signupAt);
    const c = by.get(k) ?? blank();
    for (const t of [c, tot]) {
      t.created++;
      if (f.woke) t.woke++;
      if (f.multiplayer) t.multiplayer++;
      if (f.prompted) t.prompted++;
      if (f.clickedAt) t.clicked++;
      // Paid = a payment at or after the free server was created (an earlier payment is not an upgrade FROM free).
      const paid = !!f.paidAt && f.paidAt >= f.createdAt;
      if (paid) t.paid++;
      if (paid && f.clickedAt && f.paidAt! >= f.clickedAt) t.paidAfterClick++;
    }
    by.set(k, c);
  }
  const fin = (c: ReturnType<typeof blank>) => ({
    ...c,
    createdToMultiplayerPct: pct(c.multiplayer, c.created),
    createdToPaidPct: pct(c.paid, c.created),
  });
  return {
    cohorts: [...by.entries()].sort((a, b) => (a[0] < b[0] ? -1 : 1)).map(([week, c]) => ({ week, ...fin(c) })),
    totals: fin(tot),
  };
}

export async function freeMcFunnel(from: Date, to: Date): Promise<FreeMcFunnel> {
  // Cohort members: owners of a free server whose ACCOUNT was created in [from, to).
  const servers = await db.freeMinecraftServer.findMany({
    where: { user: { ...CUSTOMER_WHERE, createdAt: { gte: from, lt: to } } },
    select: {
      id: true, userId: true, createdAt: true, firstWakeAt: true, firstMultiplayerAt: true,
      user: { select: { createdAt: true } },
    },
    take: 50_000,
  });
  const ids = servers.map((s) => s.userId);
  const sids = servers.map((s) => s.id);

  const [wakeEv, multiSamples, upsell, cash, debit] = ids.length
    ? await Promise.all([
        db.freeMinecraftEvent.groupBy({ by: ["serverId"], where: { serverId: { in: sids }, kind: "WAKE" }, _count: { _all: true } }),
        db.freeMinecraftSample.groupBy({ by: ["serverId"], where: { serverId: { in: sids }, playersOnline: { gte: 2 } }, _count: { _all: true } }),
        db.freeMinecraftUpsellEvent.groupBy({ by: ["userId", "trigger", "action"], where: { userId: { in: ids } }, _min: { at: true } }),
        db.walletTransaction.groupBy({ by: ["userId"], where: { ...REAL_CASH_IN_WHERE, userId: { in: ids } }, _min: { createdAt: true } }),
        db.walletTransaction.groupBy({ by: ["userId"], where: { ...REVENUE_WHERE, userId: { in: ids } }, _min: { createdAt: true } }),
      ])
    : [[], [], [], [], []] as const;

  const wakeSet = new Set(wakeEv.map((w) => w.serverId));
  const multiSet = new Set(multiSamples.map((m) => m.serverId));
  const shown = new Set<string>();
  const clickedAt = new Map<string, Date>();
  for (const u of upsell) {
    if (u.action === "SHOWN") shown.add(u.userId);
    if (u.action === "CLICKED" && u._min.at) {
      const c = clickedAt.get(u.userId);
      if (!c || u._min.at < c) clickedAt.set(u.userId, u._min.at);
    }
  }
  const paidAt = new Map<string, Date>();
  for (const r of [...cash, ...debit]) {
    const d = r._min.createdAt;
    if (!d) continue;
    const c = paidAt.get(r.userId);
    if (!c || d < c) paidAt.set(r.userId, d);
  }

  let wokeCol = 0, wokeFb = 0, multiCol = 0, multiFb = 0;
  const facts: ServerFact[] = servers.map((s) => {
    const wokeC = !!s.firstWakeAt;
    const wokeF = !wokeC && wakeSet.has(s.id);
    const multC = !!s.firstMultiplayerAt;
    const multF = !multC && multiSet.has(s.id);
    if (wokeC) wokeCol++;
    if (wokeF) wokeFb++;
    if (multC) multiCol++;
    if (multF) multiFb++;
    return {
      userId: s.userId,
      signupAt: s.user.createdAt,
      createdAt: s.createdAt,
      woke: wokeC || wokeF,
      multiplayer: multC || multF,
      prompted: shown.has(s.userId),
      clickedAt: clickedAt.get(s.userId) ?? null,
      paidAt: paidAt.get(s.userId) ?? null,
    };
  });
  const { cohorts, totals } = buildCohorts(facts);

  // Per-trigger click-through among these owners (distinct users).
  const trig = new Map<string, { shown: Set<string>; clicked: Set<string> }>();
  for (const u of upsell) {
    const t = trig.get(u.trigger) ?? { shown: new Set<string>(), clicked: new Set<string>() };
    if (u.action === "SHOWN") t.shown.add(u.userId);
    if (u.action === "CLICKED") t.clicked.add(u.userId);
    trig.set(u.trigger, t);
  }
  const triggers = [...trig.entries()]
    .map(([trigger, t]) => ({ trigger, shownUsers: t.shown.size, clickedUsers: t.clicked.size, clickRatePct: pct(t.clicked.size, t.shown.size) }))
    .sort((a, b) => b.shownUsers - a.shownUsers);

  // Top of funnel: human views of /free-minecraft*.
  const exIps = await excludedIps();
  const vis = await db.$queryRaw<{ views: bigint; visitors: bigint }[]>(Prisma.sql`
    SELECT COUNT(*) AS views, COUNT(DISTINCT COALESCE("visitorId", "ip")) AS visitors
    FROM "Visit"
    WHERE "createdAt" >= ${from} AND "createdAt" < ${to} AND "isBot" = false
      AND ("path" = '/free-minecraft' OR "path" LIKE '/free-minecraft/%' OR "path" LIKE '/free-minecraft?%')
      ${exIps.length ? Prisma.sql`AND "ip" NOT IN (${Prisma.join(exIps)})` : Prisma.empty}`);

  return {
    from: from.toISOString(),
    to: to.toISOString(),
    humanVisits: Number(vis[0]?.views ?? 0),
    humanVisitors: Number(vis[0]?.visitors ?? 0),
    totals,
    cohorts,
    triggers,
    coverage: { createdTotal: servers.length, wokeFromColumn: wokeCol, wokeFromFallback: wokeFb, multiplayerFromColumn: multiCol, multiplayerFromFallback: multiFb },
    notes: [
      "First-wake and first-2-players are stamped by the health sweep from the day this ships; older servers fall back to remaining events (90 days) and samples (14 days), so their counts are lower bounds.",
      "Prompted means an upgrade prompt was actually shown to the owner (it needs the upsell flag on and a real signal on that server); it is not the number of owners who could have seen one.",
      "Paid counts a real payment or earned revenue on or after the free server was created.",
      `Cohort = week the owner's account was created (UTC, Monday start). Window ${weekKey(from)} to ${weekKey(new Date(to.getTime() - DAY))}.`,
    ],
  };
}

export { weekStartUtc };
