export type GmailPostfixStats = { sampled: number; gmailLines: number; sent: number; deferred: number; bounced: number };

/**
 * Recent postfix delivery attempts to Gmail only (relay=gmail-smtp-in...), for the
 * growth scoreboard's "Gmail deferral rate" (mkt-033). Same log sample as `mcStats`;
 * it is a SAMPLE of the last `sample` log lines, not a full-period count — callers
 * must label it so. Throws MailcowError when not configured / unreachable.
 */
export async function mcGmailPostfixStats(sample = 1000): Promise<GmailPostfixStats> {
  config();
  const raw = asArray(await mcRequest("GET", `/get/logs/postfix/${sample}`));
  const out: GmailPostfixStats = { sampled: raw.length, gmailLines: 0, sent: 0, deferred: 0, bounced: 0 };
  for (const entry of raw) {
    const msg = String(
      (entry as { message?: unknown })?.message ?? (entry && typeof entry === "object" ? JSON.stringify(entry) : entry) ?? "",
    ).toLowerCase();
    if (!/relay=(gmail-smtp-in|[a-z0-9.-]*\.google(mail)?\.com)/.test(msg)) continue;
    if (msg.includes("status=sent")) out.sent++;
    else if (msg.includes("status=deferred")) out.deferred++;
    else if (msg.includes("status=bounced")) out.bounced++;
    else continue;
    out.gmailLines++;
  }
  return out;
}
