    week: { human: TrafficQuality["human"]; raw: TrafficQuality["raw"]; botSharePct: number | null };
    prev: { human: TrafficQuality["human"]; raw: TrafficQuality["raw"]; botSharePct: number | null };
    devices: TrafficQuality["devices"];
    countries: TrafficQuality["countries"];
  };
  funnel: HumanFunnel;
  signups: { week: number; prev: number; verifiedWeek: number };
  cohorts: CohortRow[];
  timeToFirstServer: { medianMinutes: number | null; n: number };
  wizard: { windowDays: 7; note: string; products: { product: string; started: number; completed: number; steps: StepConv[] }[] };
  partners: { attachedWeek: number; attachedPrev: number; referralSignupsWeek: number; referralSignupsPrev: number };
  mail: { gmail: null | { sampled: number; gmailLines: number; sent: number; deferred: number; bounced: number; deferralPct: number | null }; unavailableReason: string | null };
  reviews: { trustpilotRecorded: number; trustpilotApproved: number };
  freeMc: { signupWeekCohort: FreeMcFunnel["totals"]; humanVisitsToFreeMcPage: number };
  notes: string[];
};

async function firstEvents(ids: string[]) {
  const pay = new Map<string, Date>();
  const deploy = new Map<string, Date>();
  if (!ids.length) return { pay, deploy };
  const [cash, debit, servers, freemc] = await Promise.all([
    db.walletTransaction.groupBy({ by: ["userId"], where: { ...REAL_CASH_IN_WHERE, userId: { in: ids } }, _min: { createdAt: true } }),
    db.walletTransaction.groupBy({ by: ["userId"], where: { ...REVENUE_WHERE, userId: { in: ids } }, _min: { createdAt: true } }),
    db.server.groupBy({ by: ["userId"], where: { userId: { in: ids } }, _min: { createdAt: true } }),
    db.freeMinecraftServer.findMany({ where: { userId: { in: ids } }, select: { userId: true, createdAt: true } }),
  ]);
  const setMin = (m: Map<string, Date>, id: string, d: Date | null | undefined) => {
    if (!d) return;
    const c = m.get(id);
    if (!c || d < c) m.set(id, d);
  };
  for (const r of [...cash, ...debit]) setMin(pay, r.userId, r._min.createdAt);
  for (const r of servers) setMin(deploy, r.userId, r._min.createdAt);
  for (const f of freemc) setMin(deploy, f.userId, f.createdAt);
  return { pay, deploy };
}

export async function buildScoreboard(weekStart: Date, now: Date = new Date()): Promise<Scoreboard> {
  const weekEnd = new Date(weekStart.getTime() + 7 * DAY);
  const prevStart = new Date(weekStart.getTime() - 7 * DAY);
  const notes: string[] = [];

  const [tq, tqPrev, funnel, freeMc] = await Promise.all([
    trafficQuality(weekStart, weekEnd),
    trafficQuality(prevStart, weekStart),
    humanFunnel(weekStart, weekEnd),
    freeMcFunnel(weekStart, weekEnd),
  ]);

  // ---- weekly signup cohorts (last COHORT_WEEKS up to and including this week) ----
  const cohortStarts = Array.from({ length: COHORT_WEEKS }, (_, i) => new Date(weekStart.getTime() - (COHORT_WEEKS - 1 - i) * 7 * DAY));
  const users = await db.user.findMany({
    where: { ...CUSTOMER_WHERE, createdAt: { gte: cohortStarts[0], lt: weekEnd } },
    select: { id: true, createdAt: true, emailVerifiedAt: true, referredById: true },
    take: 100_000,
  });
  const ev = await firstEvents(users.map((u) => u.id));
  const cohorts: CohortRow[] = cohortStarts.map((cs) => {
    const members = users.filter((u) => u.createdAt >= cs && u.createdAt < new Date(cs.getTime() + 7 * DAY));
    const m7 = cohortMature(cs, 7, now);
    const m30 = cohortMature(cs, 30, now);
    const p7 = members.filter((u) => withinDays(u.createdAt, ev.pay.get(u.id), 7)).length;
    const p30 = members.filter((u) => withinDays(u.createdAt, ev.pay.get(u.id), 30)).length;
    return {
      week: weekKey(cs),
      signups: members.length,
      paid7: m7 ? p7 : null,
      paid30: m30 ? p30 : null,
      paid7Pct: m7 ? pct(p7, members.length) : null,
      paid30Pct: m30 ? pct(p30, members.length) : null,
      deployedEver: members.filter((u) => ev.deploy.has(u.id)).length,
    };
  });

  const inWeek = users.filter((u) => u.createdAt >= weekStart && u.createdAt < weekEnd);
  const inPrev = users.filter((u) => u.createdAt >= prevStart && u.createdAt < weekStart);
  const ttfs = inWeek
    .map((u) => ev.deploy.get(u.id))
    .map((d, i) => (d ? d.getTime() - inWeek[i].createdAt.getTime() : null))
    .filter((x): x is number => x != null && x >= 0);

  // ---- wizard step conversion (rolling 7 days at generation time) ----
  let wizardProducts: Scoreboard["wizard"]["products"] = [];
  try {
    const funnels = await deployFunnels(7);
    wizardProducts = funnels
      .filter((f) => f.product === "vps" || f.product === "game")
      .map((f) => ({ product: f.product, started: f.started, completed: f.completed, steps: stepConversion(f.steps.map((s) => ({ step: s.step, reached: s.reached }))) }));
  } catch (e) {
    notes.push(`Wizard step data unavailable: ${e instanceof Error ? e.message : String(e)}`);
  }

  // ---- partner / referral customers ----
  const [partnerWeek, partnerPrev] = await Promise.all([
    db.partnerCustomer.count({ where: { attachedAt: { gte: weekStart, lt: weekEnd } } }),
    db.partnerCustomer.count({ where: { attachedAt: { gte: prevStart, lt: weekStart } } }),
  ]);

  // ---- Gmail deferral (sample from the mail server's postfix log) ----
  let gmail: Scoreboard["mail"]["gmail"] = null;
  let unavailableReason: string | null = null;
  try {
    const g = await mcGmailPostfixStats(1000);
    gmail = { ...g, deferralPct: deferralRate(g.sent, g.deferred, g.bounced) };
    if (g.gmailLines === 0) notes.push("No Gmail delivery lines in the sampled postfix log, so no deferral rate was computed.");
  } catch (e) {
    unavailableReason = e instanceof Error ? e.message : String(e);
  }

  // ---- reviews ----
  const [tpAll, tpApproved] = await Promise.all([
    db.review.count({ where: { source: "TRUSTPILOT" } }),
    db.review.count({ where: { source: "TRUSTPILOT", approved: true } }),
  ]);

  notes.push(
    "Traffic is human-only (isBot = false, admin-excluded IPs removed); the raw figure is shown beside it.",
    "Signups are customer accounts created in the period, internal/test accounts excluded. 'Verified' is the subset that confirmed their email.",
    "Signup-to-paid is null for a cohort that has not yet had the full 7 or 30 days. Paid = a real payment or earned revenue.",
    "Gmail deferral is a sample of recent postfix log lines, not the whole week.",
    "Trustpilot is the count of Trustpilot reviews recorded in admin, entered by hand.",
  );

  return {
    version: 1,
    generatedAt: now.toISOString(),
    weekStart: weekStart.toISOString(),
    weekEnd: weekEnd.toISOString(),
    traffic: {
      week: { human: tq.human, raw: tq.raw, botSharePct: tq.botSharePct },
      prev: { human: tqPrev.human, raw: tqPrev.raw, botSharePct: tqPrev.botSharePct },
      devices: tq.devices,
      countries: tq.countries,
    },
    funnel,
    signups: { week: inWeek.length, prev: inPrev.length, verifiedWeek: inWeek.filter((u) => u.emailVerifiedAt).length },
    cohorts,
    timeToFirstServer: { medianMinutes: median(ttfs) == null ? null : Math.round(median(ttfs)! / 60_000), n: ttfs.length },
    wizard: { windowDays: 7, note: "Rolling 7 days at generation time (sessions that started the wizard), not the calendar week.", products: wizardProducts },
    partners: {
      attachedWeek: partnerWeek,
      attachedPrev: partnerPrev,
      referralSignupsWeek: inWeek.filter((u) => u.referredById).length,
      referralSignupsPrev: inPrev.filter((u) => u.referredById).length,
    },
    mail: { gmail, unavailableReason },
    reviews: { trustpilotRecorded: tpAll, trustpilotApproved: tpApproved },
    freeMc: { signupWeekCohort: freeMc.totals, humanVisitsToFreeMcPage: freeMc.humanVisits },
    notes,
  };
}

/** Build and upsert the report for `weekStart`. Idempotent per week. */
export async function generateGrowthReport(weekStart: Date, trigger: "auto" | "manual", now: Date = new Date()) {
  const data = await buildScoreboard(weekStart, now);
  const json = JSON.parse(JSON.stringify(data));
  return db.growthReport.upsert({
    where: { weekStart },
    update: { data: json, generatedAt: now, trigger },
    create: { weekStart, data: json, generatedAt: now, trigger },
  });
}

/** Plain-text digest of a report (the optional email body). */
export function scoreboardText(s: Scoreboard): string {
  const f = (n: number | null, suffix = "") => (n == null ? "n/a" : `${n}${suffix}`);
  const last = s.cohorts[s.cohorts.length - 1];
  const lines = [
    `Nxeon growth scoreboard, week of ${s.weekStart.slice(0, 10)}`,
    "",
    `Human visitors: ${s.traffic.week.human.visitors} (previous week ${s.traffic.prev.human.visitors}); bot share of page views ${f(s.traffic.week.botSharePct, "%")}`,
    `Signups: ${s.signups.week} (previous ${s.signups.prev}); email-verified ${s.signups.verifiedWeek}`,
    `Sessions that opened /register: ${s.funnel.registerSessions} of ${s.funnel.humanSessions} human sessions`,
    `This week's signups: deployed ${s.funnel.deployed}, paid ${s.funnel.paid} so far`,
    `Time to first server (median): ${f(s.timeToFirstServer.medianMinutes, " min")} (n=${s.timeToFirstServer.n})`,
    `Partner customers attached: ${s.partners.attachedWeek}; referral signups: ${s.partners.referralSignupsWeek}`,
    `Gmail deferral (log sample): ${s.mail.gmail ? f(s.mail.gmail.deferralPct, "%") : "unavailable"}`,
    `Trustpilot reviews recorded: ${s.reviews.trustpilotRecorded}`,
    `Free Minecraft (this week's signups): created ${s.freeMc.signupWeekCohort.created}, 2+ players ${s.freeMc.signupWeekCohort.multiplayer}, paid ${s.freeMc.signupWeekCohort.paid}`,
    "",
    "Signup-to-paid by weekly cohort (7d / 30d):",
    ...s.cohorts.map((c) => `  ${c.week}: ${c.signups} signups, ${f(c.paid7Pct, "%")} / ${f(c.paid30Pct, "%")}`),
    "",
    `Latest cohort ${last?.week ?? ""} is shown as n/a until its window has fully elapsed.`,
  ];
  return lines.join("\n");
}

/**
 * Optional email. Returns "disabled" unless BOTH the flag and a recipient are set;
 * never throws; marks `emailedAt` so a week is sent at most once.
 */
export async function maybeEmailReport(reportId: string): Promise<"disabled" | "sent" | "failed" | "already"> {
  if (!(await getSettingBool("growth_scoreboard_email_enabled", false))) return "disabled";
  const to = (await getSetting("growth_scoreboard_email_to")).trim();
  if (!to) return "disabled";
  const row = await db.growthReport.findUnique({ where: { id: reportId } });
  if (!row) return "failed";
  if (row.emailedAt) return "already";
  try {
    const { sendMail } = await import("@/lib/mailer");
    const data = row.data as unknown as Scoreboard;
    const text = scoreboardText(data);
    const ok = await sendMail({ to, subject: `Nxeon growth scoreboard, week of ${data.weekStart.slice(0, 10)}`, html: `<pre style="font-family:monospace;font-size:13px">${text.replace(/&/g, "&amp;").replace(/</g, "&lt;")}</pre>`, text } as never);
    if (!ok) return "failed";
    await db.growthReport.update({ where: { id: reportId }, data: { emailedAt: new Date() } });
    return "sent";
  } catch {
    return "failed";
  }
}
