"use server";

import { revalidatePath } from "next/cache";
import { requireArea } from "./rbac";
import { recordAudit } from "./audit";
import { generateGrowthReport } from "./growth/scoreboard";
import { lastCompletedWeekStart, weekStartUtc } from "./growth/pure";

/**
 * Admin "Generate now" for the growth scoreboard (mkt-033). Read-only analytics
 * that writes one GrowthReport row; sends nothing. `current` builds the in-progress
 * week to date (cohort rates will correctly read n/a).
 */
export async function generateGrowthReportNow(which: "last" | "current"): Promise<{ ok?: true; week?: string; error?: string }> {
  const admin = await requireArea("analytics");
  const now = new Date();
  const start = which === "current" ? weekStartUtc(now) : lastCompletedWeekStart(now);
  try {
    await generateGrowthReport(start, "manual", now);
  } catch (e) {
    return { error: e instanceof Error ? e.message.slice(0, 200) : "Failed to build the report." };
  }
  await recordAudit(admin.id, "growth.report_generate", `${which} ${start.toISOString().slice(0, 10)}`);
  revalidatePath("/admin/growth");
  return { ok: true, week: start.toISOString().slice(0, 10) };
}
