// Weekly growth scoreboard sweep (mkt-033). Builds the report for the last COMPLETED
// Mon-Sun UTC week once it is missing (catches up if the worker was down on Monday).
// Writes one GrowthReport row; sends nothing unless the owner enabled the default-OFF
// email flag AND set a recipient (lib/growth/scoreboard.ts maybeEmailReport).
import { db } from "../lib/db";
import { getSettingBool } from "../lib/settings";
import { generateGrowthReport, maybeEmailReport } from "../lib/growth/scoreboard";
import { lastCompletedWeekStart } from "../lib/growth/pure";

export async function growthReportSweep(): Promise<void> {
  if (!(await getSettingBool("growth_scoreboard_auto", true))) return;
  const now = new Date();
  // Give the first hour of Monday UTC to late close-beacons / rollups before reading the week.
  if (now.getUTCDay() === 1 && now.getUTCHours() < 1) return;
  const start = lastCompletedWeekStart(now);
  let row = await db.growthReport.findUnique({ where: { weekStart: start } });
  if (!row) row = await generateGrowthReport(start, "auto", now);
  if (!row.emailedAt) await maybeEmailReport(row.id);
}
